package main

import (
	"encoding/json"
	"fmt"
	"io"
	"log"
	"os"
	"sync"

	"github.com/jepsen-io/maelstrom/demo/go"
)

var counter int64
var mu sync.Mutex

func handleInit(ctx *go.InitContext, msg go.Message) {
	node := ctx.NodeInfo.ID.String()
	log.Printf("Node %s initialized with peers: %v", node, ctx.NodeInfo.Peers)

	// Respond to init by sending the node ID
	ctx.Reply(msg, go.Body{
		"type": "init_ack",
		"id":   node,
	})
}

func handleIssue(ctx *go.HandleContext, msg go.Message) {
	body := &struct {
		Type      string `json:"type"`
		MsgID     int64  `json:"msg_id"`
	}{}

	if err := json.Unmarshal(msg.Body, body); err != nil {
		log.Printf("Error parsing issue message: %v", err)
		return
	}

	mu.Lock()
	ticket := fmt.Sprintf("%s-%d", ctx.NodeInfo.ID.String(), counter+1)
	counter++
	var ack go.Acknowledgment
	if err := json.Unmarshal(msg.Raw, &ack); err != nil {
		log.Printf("Error parsing ack: %v", err)
	} else {
		mu.Unlock()
		ctx.Reply(ack, go.Body{
			"type":      "issued",
			"in_reply_to": ack.MsgID,
			"ticket": ticket,
		})
	}
}

func main() {
	node := maelstrom.NewNode()
	node.Handle(go.Type("init"), handleInit)
	node.Handle(go.Type("issue"), handleIssue)

	// Run the node, listening on stdin/stdout
	os.Exit(node.Run(os.Stdin, os.Stdout))
}

