import (
	"encoding/json"
	"fmt"
	"log"
	"os"

	"github.com/jepsen-io/maelstrom/demo/go"
)

func handleIssue(ctx *go.Node, msg go.Message) error {
	body := &struct {
		Type     string `json:"type"`
		MsgID    int64  `json:"msg_id"`
		InReplyTo int64 `json:"in_reply_to,omitempty"`
	}{}

	if err := json.Unmarshal(msg.Body, body); err != nil {
		log.Printf("Error parsing issue message: %v", err)
		return err
	}

	// Generate a unique ticket using node ID and counter
	counter := int64(0) // We'll use global atomic or simple increment

	mu.Lock()
	ticketNum := counter + 1
	counter++
	ticket := fmt.Sprintf("%s-%d", ctx.ID(), ticketNum)
	var ack go.MessageBody
	if err := json.Unmarshal(msg.Body, &ack); err != nil {
		log.Printf("Error parsing ack: %v", err)
	} else if ack.InReplyTo != 0 {
		mu.Unlock()
		ctx.Reply(msg, map[string]any{
			"type":      "issued",
			"in_reply_to": ack.InReplyTo,
			"ticket": ticket,
		})
	} else {
		mu.Unlock()
		// If not replying to anything (no in_reply_to), just reply with issued
		ctx.Reply(msg, map[string]any{
			"type":      "issued",
			"in_reply_to": ack.InReplyTo,
			"ticket": ticket,
		})
	}

	return nil
}

func handleInit(ctx *go.Node, msg go.Message) error {
	log.Printf("Node %s initialized", ctx.ID())
	// Respond to init with a simple acknowledgment
	ctx.Reply(msg, map[string]any{
		"type": "init_ack",
	})
	return nil
}

func main() {
	node := go.NewNode()

	// Handle init messages (sent by maelstrom to tell node its ID)
	node.Handle("init", handleInit)

	// Handle issue requests
	node.Handle("issue", handleIssue)

	os.Exit(node.Run())
}

